// Smooth exact MHD contact advects at v=.4 without changing p,v,B,q.
// Deterministic local masks include the periodic seam, and exercise mixed
// first-order HLLE/high-order HLLD shared fluxes in both RK stages.
std::array<double,3> contact(int n){
 double g=1.5,dx=1./n,time=0,maximum_residual=0;std::vector<A>u(n),v(n),rhs(n),p(n),f(n+1);std::vector<unsigned char>mark(n);
 for(int i=0;i<n;++i){double x=(i+.5)*dx;A z={1+.2*std::cos(2*PI*x),.4,.03,-.02,.7,.75,.5,-.1,.1};u[i]=conserved(z,g);mark[i]=(i%17==0);}
 auto sum=[&](const std::vector<A>&s){std::array<long double,9> z={};for(auto&a:s)for(int k=0;k<9;++k)z[k]+=(long double)a[k]*dx;return z;};auto initial=sum(u);
 auto calc=[&](const std::vector<A>&s){for(int i=0;i<n;++i)if(!primitive(s[i],p[i],g))throw std::runtime_error("Contact positivity failed");for(int i=0;i<=n;++i){int a=(i+n-1)%n,b=i%n;bool low=mark[a]||mark[b];A l=p[a],r=p[b];if(!low)for(int k=0;k<9;++k){l[k]+=.5*limiter(p[a][k]-p[(a+n-1)%n][k],p[b][k]-p[a][k]);r[k]-=.5*limiter(p[b][k]-p[a][k],p[(b+1)%n][k]-p[b][k]);}f[i]=riemann(l,r,{1,0,0},1,g,2,low);}if(f[0]!=f[n])throw std::runtime_error("Seam face flux differs");for(int i=0;i<n;++i)for(int k=0;k<9;++k)rhs[i][k]=-(f[i+1][k]-f[i][k])/dx;};
 while(time<.3-1e-13){double h=std::min(.1*dx,.3-time);calc(u);for(int i=0;i<n;++i)for(int k=0;k<9;++k)v[i][k]=u[i][k]+h*rhs[i][k];calc(v);for(int i=0;i<n;++i)for(int k=0;k<9;++k)u[i][k]=.5*(u[i][k]+v[i][k]+h*rhs[i][k]);time+=h;auto z=sum(u);for(int k=0;k<9;++k)maximum_residual=std::max(maximum_residual,double(std::abs(z[k]-initial[k])/(1+std::abs(initial[k]))));}
 double error=0,cosine=0,sine=0;for(int i=0;i<n;++i){double x=(i+.5)*dx;error+=std::abs(u[i][0]-(1+.2*std::cos(2*PI*(x-.4*time))))*dx;cosine+=(u[i][0]-1)*std::cos(2*PI*x);sine+=(u[i][0]-1)*std::sin(2*PI*x);}
 double speed=std::atan2(sine,cosine)/(2*PI*time);if(maximum_residual>1e-13||std::abs(speed-.4)>.002)throw std::runtime_error("Contact conservation/speed gate failed");return {error,speed,maximum_residual};
}
